  },
  [NODE_TYPES.LIST_OPERATOR]: {
    required: ['filter_conditions'],
  },
  [NODE_TYPES.LOOP]: {
    required: ['loop_conditions'],
  },
  [NODE_TYPES.LOOP_START]: {
    required: [],
  },
  [NODE_TYPES.LOOP_END]: {
    required: [],
  },
