  type DifyNode,
  EDGE_TYPES,
  type EdgeType,
  NODE_TYPES,
  type NodeType,
  type NodeTypeValidation,
  type ValidationContext,
} from './types';

const NODE_VALIDATIONS: Record<NodeType, NodeTypeValidation> = {
  [NODE_TYPES.START]: {
    required: ['variables'],
  },
  [NODE_TYPES.END]: {
    required: ['outputs'],
  },
  [NODE_TYPES.LLM]: {
    required: ['model', 'prompt_template'],
    validations: {
      model: {
        required: ['provider', 'name'],
      },
    },
  },
  [NODE_TYPES.IF_ELSE]: {
    required: [], // if-else node structure varies, no required fields for now
  },
  [NODE_TYPES.TEMPLATE_TRANSFORM]: {
